#include "pe_state.h"
#include "pe1/dialogue_alpha.h"
#include "pe_state_boundary.h"
#include "psyz/state_gpu.h"
#include <string.h>
#define GPU_BYTES (16u+PSYZ_STATE_NATIVE_VRAM_BYTES+PSYZ_STATE_GPU_CONTROL_BYTES+PSYZ_STATE_DUCK_BYTES+PE_DIALOGUE_STATE_BYTES)
static int validate(void *ctx,const unsigned char *in,size_t n){(void)ctx;return in&&n==GPU_BYTES&&!memcmp(in,"PEVRAM04",8)&&in[8]==0&&in[9]==4&&in[10]==0&&in[11]==2&&in[12]==4&&in[13]==0&&in[14]==0&&in[15]==0&&Psyz_StateGpuControlValidate(in+16+PSYZ_STATE_NATIVE_VRAM_BYTES,PSYZ_STATE_GPU_CONTROL_BYTES)&&Psyz_StateDuckValidate(in+16+PSYZ_STATE_NATIVE_VRAM_BYTES+PSYZ_STATE_GPU_CONTROL_BYTES,PSYZ_STATE_DUCK_BYTES)&&PeDialogue_StateValidate(in+16+PSYZ_STATE_NATIVE_VRAM_BYTES+PSYZ_STATE_GPU_CONTROL_BYTES+PSYZ_STATE_DUCK_BYTES,PE_DIALOGUE_STATE_BYTES);}
static int capture(void *ctx,unsigned char *out,size_t cap,size_t *used){(void)ctx;if(used)*used=0;if(!used||!out||cap<GPU_BYTES||!PeStateBoundary_AtCpuPoint()||!Psyz_StateGpuBegin())return 0;memcpy(out,"PEVRAM04",8);const unsigned char meta[8]={0,4,0,2,4,0,0,0};memcpy(out+8,meta,8);int ok=Psyz_StateGpuControlCapture(out+16+PSYZ_STATE_NATIVE_VRAM_BYTES,PSYZ_STATE_GPU_CONTROL_BYTES)&&Psyz_StateGpuCapture(out+16,PSYZ_STATE_NATIVE_VRAM_BYTES)&&Psyz_StateDuckCapture(out+16+PSYZ_STATE_NATIVE_VRAM_BYTES+PSYZ_STATE_GPU_CONTROL_BYTES,PSYZ_STATE_DUCK_BYTES,out+16,PSYZ_STATE_NATIVE_VRAM_BYTES)&&PeDialogue_StateCapture(out+16+PSYZ_STATE_NATIVE_VRAM_BYTES+PSYZ_STATE_GPU_CONTROL_BYTES+PSYZ_STATE_DUCK_BYTES,PE_DIALOGUE_STATE_BYTES);Psyz_StateGpuEnd();if(ok)*used=GPU_BYTES;return ok;}
static int restore(void *ctx,const unsigned char *in,size_t n){if(!validate(ctx,in,n)||!PeStateBoundary_AtCpuPoint()||!Psyz_StateGpuBegin())return 0;int ok=Psyz_StateGpuRestore(in+16,PSYZ_STATE_NATIVE_VRAM_BYTES)&&Psyz_StateGpuControlRestore(in+16+PSYZ_STATE_NATIVE_VRAM_BYTES,PSYZ_STATE_GPU_CONTROL_BYTES)&&Psyz_StateDuckRestore(in+16+PSYZ_STATE_NATIVE_VRAM_BYTES+PSYZ_STATE_GPU_CONTROL_BYTES,PSYZ_STATE_DUCK_BYTES,in+16,PSYZ_STATE_NATIVE_VRAM_BYTES)&&PeDialogue_StateRestore(in+16+PSYZ_STATE_NATIVE_VRAM_BYTES+PSYZ_STATE_GPU_CONTROL_BYTES+PSYZ_STATE_DUCK_BYTES,PE_DIALOGUE_STATE_BYTES);Psyz_StateGpuEnd();return ok;}
int PeState_RegisterNativeVram(PeStateRegistry *r){PeStateModule m={PE_STATE_GPU,4,GPU_BYTES,capture,0,validate,restore,0};return PeState_Register(r,m);}
